dtsPropsFor.AppButton:
/** `link` renders a router link with a button's shape; `button` and `submit` render a <button>. */
type: "button" | "submit" | "link";
/** Four roles, not six colours. `destructive` is danger text, never a red fill. */
colour: "primary" | "secondary" | "ghost" | "destructive";
/** Where the button goes. Required when `type="link"`, unused otherwise. */
to?: string;
/** The control scale: `md` (48px) is the default, `sm` the 44px tap floor, `lg` a form's submit, `inline` a quiet action inside a line of copy. */
size?: "inline" | "sm" | "md" | "lg";
/** Most buttons fill their column; `auto` shrinks one to its content. */
width?: "full" | "auto";
disabled?: boolean;
onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
children?: React.ReactNode;
/** Positions the button. Its own styling is never replaced. */
className?: string;

dtsPropsFor.AppNumberField:
/** The committed number, or `undefined` while the field is empty. */
value: number | undefined;
onChange: (value: number | undefined) => void;
/** A unit drawn inside the field's border, as a label on it rather than a control in it. */
unit?: string;
/** `decimal` for a weight, `numeric` for a count — never `type="number"`. */
inputMode?: "decimal" | "numeric";
placeholder?: string;
className?: string;
